package br.com.onda;
import android.content.Context;import java.net.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.util.*;import java.util.function.Consumer;
/** Finite user-triggered requests. Disk thumbnails reused; no timers or prefetch. */
final class ImageNetwork {
 static List<ImageCatalog.Photo> search(String query,int offset,Consumer<HttpURLConnection> active)throws Exception{return ImageCatalog.parse(new String(read(ImageCatalog.endpoint(query,offset),3*1024*1024,active),StandardCharsets.UTF_8));}
 static File cached(Context c,String url){try{byte[] hash=MessageDigest.getInstance("SHA-256").digest(ImageCatalog.mediaUrl(url).getBytes(StandardCharsets.UTF_8));StringBuilder name=new StringBuilder();for(byte b:hash)name.append(String.format(Locale.ROOT,"%02x",b&255));File root=new File(c.getCacheDir(),"image-thumbs");root.mkdirs();return new File(root,name.toString());}catch(Exception e){throw new IllegalArgumentException(e);}}
 static File image(Context c,String url,Consumer<HttpURLConnection> active)throws Exception{File file=cached(c,url);if(file.isFile()&&file.length()>0){file.setLastModified(System.currentTimeMillis());return file;}byte[] bytes=read(ImageCatalog.mediaUrl(url),12*1024*1024,active);File tmp=File.createTempFile("photo-",".part",file.getParentFile());try{try(OutputStream out=new FileOutputStream(tmp)){out.write(bytes);}if(Thread.currentThread().isInterrupted())throw new InterruptedIOException();if(!tmp.renameTo(file))throw new IOException("Não foi possível guardar a imagem.");trim(file.getParentFile(),file);return file;}finally{tmp.delete();}}
 private static void trim(File root,File keep){File[] files=root.listFiles();if(files==null)return;Arrays.sort(files,Comparator.comparingLong(File::lastModified));long total=0;for(File f:files)total+=f.length();for(File f:files)if(total>24*1024*1024&&!f.equals(keep)){long size=f.length();if(f.delete())total-=size;}}
 private static byte[] read(String url,int max,Consumer<HttpURLConnection> active)throws IOException{for(int redirects=0;redirects<4;redirects++){if(Thread.currentThread().isInterrupted())throw new InterruptedIOException();HttpURLConnection connection=(HttpURLConnection)new URL(url).openConnection();active.accept(connection);try{connection.setInstanceFollowRedirects(false);connection.setConnectTimeout(15000);connection.setReadTimeout(15000);connection.setRequestProperty("User-Agent","Onda/0.68.0 (Android image search; https://github.com/cristianoarakaki-cpu/Arakaki)");int status=connection.getResponseCode();if(status>=300&&status<400){String next=new URL(new URL(url),connection.getHeaderField("Location")).toString();url=url.contains("/w/api.php")?ImageCatalog.pageUrl(next):ImageCatalog.mediaUrl(next);continue;}if(status!=200)throw new IOException("A fonte de imagens respondeu HTTP "+status+". Tente novamente mais tarde.");try(InputStream in=connection.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buffer=new byte[16384];int n;while((n=in.read(buffer))!=-1){if(Thread.currentThread().isInterrupted())throw new InterruptedIOException();if(out.size()+n>max)throw new IOException("A prévia é muito grande. Escolha outra imagem.");out.write(buffer,0,n);}return out.toByteArray();}}finally{connection.disconnect();active.accept(null);}}throw new IOException("Muitos redirecionamentos na imagem.");}
}
